using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanBeCreated()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context);
        }

        [Fact]
        public void SchoolContext_HasStudentsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Students);
        }

        [Fact]
        public void SchoolContext_HasCoursesDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Courses);
        }

        [Fact]
        public void SchoolContext_HasDepartmentsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Departments);
        }

        [Fact]
        public void SchoolContext_HasInstructorsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Instructors);
        }

        [Fact]
        public void SchoolContext_HasEnrollmentsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Enrollments);
        }

        [Fact]
        public void SchoolContext_HasCourseAssignmentsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.CourseAssignments);
        }

        [Fact]
        public void SchoolContext_HasOfficeAssignmentsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.OfficeAssignments);
        }

        [Fact]
        public void SchoolContext_HasNotificationsDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_HasPeopleDbSet()
        {
            using var context = TestHelpers.CreateContext();
            Assert.NotNull(context.People);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2024-01-01")
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateContext();
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = DateTime.Parse("2024-01-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 1234,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.Find(1234);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved!.Title);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_CompositeKey()
        {
            using var context = TestHelpers.CreateContext();
            TestHelpers.SeedDatabase(context);

            var assignment = context.CourseAssignments.First();
            Assert.True(assignment.CourseID > 0);
            Assert.True(assignment.InstructorID > 0);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveNotification()
        {
            using var context = TestHelpers.CreateContext();
            var notification = new Notification
            {
                EntityType = "Test",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };

            context.Notifications.Add(notification);
            context.SaveChanges();

            var retrieved = context.Notifications.First();
            Assert.Equal("Test", retrieved.EntityType);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsStudents()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_DoesNotReseedIfDataExists()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context); // call again

            Assert.Equal(8, context.Students.Count()); // still 8
        }

        [Fact]
        public void Initialize_SetsCorrectDepartmentAdministrators()
        {
            using var context = TestHelpers.CreateContext();

            DbInitializer.Initialize(context);

            var englishDept = context.Departments.Include(d => d.Administrator).First(d => d.Name == "English");
            Assert.NotNull(englishDept.Administrator);
            Assert.Equal("Abercrombie", englishDept.Administrator!.LastName);
        }
    }
}

